// @hrbr/catalog - SDK-level catalog facade over committed registry data.
import { Schema } from 'effect'
import type { CatalogAvailabilityRules, CatalogEntry } from '@hrbr/core/catalog'
import { PluginRegistryEntry as PluginRegistryEntrySchema } from '@hrbr/core/registry'
import {
  REGISTRY_CATALOG_AVAILABILITY,
  REGISTRY_CATALOG_ENTRIES,
  REGISTRY_CATALOG_LOCAL_ICONS,
  REGISTRY_CATALOG_POPULARITY,
} from '@hrbr/registry-catalog'

export type {
  CatalogAvailability,
  CatalogAvailabilityRules,
  CatalogEntry,
} from '@hrbr/core/catalog'

export function listCatalogEntries(): CatalogEntry[] {
  return PLUGIN_CATALOG.map(decorateEntry)
}

export function getCatalogEntry(slug: string): CatalogEntry | undefined {
  const entry = PLUGIN_CATALOG.find((candidate) => candidate.slug === slug)
  return entry ? decorateEntry(entry) : undefined
}

export function getCatalogAvailabilityRules(): CatalogAvailabilityRules {
  return REGISTRY_CATALOG_AVAILABILITY as CatalogAvailabilityRules
}

const LOCAL_ICON_PATHS: Record<string, string> = Object.fromEntries(
  Object.entries(
    REGISTRY_CATALOG_LOCAL_ICONS as Record<
      string,
      { readonly kind: string; readonly path?: string; readonly light?: string }
    >
  ).map(([slug, icon]) => [slug, icon.kind === 'single' ? icon.path : icon.light])
) as Record<string, string>

const registryPopularity = REGISTRY_CATALOG_POPULARITY as {
  readonly default: number
  readonly entries: Partial<Record<string, number>>
}

const PLUGIN_CATALOG: CatalogEntry[] = REGISTRY_CATALOG_ENTRIES.map((entry) =>
  Schema.decodeUnknownSync(PluginRegistryEntrySchema)(entry)
)

function decorateEntry(entry: CatalogEntry): CatalogEntry {
  const icon_url = entry.icon_url ?? LOCAL_ICON_PATHS[entry.slug]
  const popularity =
    entry.popularity ?? registryPopularity.entries[entry.slug] ?? registryPopularity.default
  const needsIcon = icon_url && icon_url !== entry.icon_url
  if (!needsIcon && popularity === entry.popularity) return entry
  return {
    ...entry,
    ...(needsIcon ? { icon_url } : {}),
    popularity,
  }
}
